'use client';

/* dnd-kit callback refs are attached to each column as documented drop targets. */
/* eslint-disable react-hooks/refs */
import { useEffect, useState, type CSSProperties, type ElementType, type ReactNode } from 'react';
import Image from 'next/image';
import { useDroppable } from '@dnd-kit/core';
import { SortableContext, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Camera, Heart, Sparkles, Star } from 'lucide-react';
import type { Column, Device, SiteElement } from '@/lib/siteDocument';
import { getElementAccessibilityProps } from '@/lib/elementAccessibility';
import { elementVisualStyle } from '@/lib/elementVisualStyle';
import SiteForm from '@/components/SiteForm';
import ImageCarousel from '@/components/ImageCarousel';
import { getAnimationClass, resolveButtonHref, type ButtonTarget } from '@/lib/elementActions';
import { getEditorCatalogItem } from '@/lib/editorCatalog';
import { normalizeAnchorId, scrollToAnchor } from '@/lib/navigation';
import SiteElementPreview, { supportsAdditionalElement } from '@/components/editor/SiteElementPreview';
import CatalogWidgetPreview from '@/components/editor/CatalogWidgetPreview';
import { getEditorWidgetDefinition } from '@/lib/editorWidgetRegistry';

type Props = {
  sectionId: string;
  columns: Column[];
  pages: Array<{ id: string; slug?: string; isHome?: boolean; title: string }>;
  device: Device;
  selectedElementId: string | null;
  onSelectElement: (columnId: string, elementId: string) => void;
  onUpdateElement: (columnId: string, elementId: string, update: (element: SiteElement) => SiteElement, historyGroup?: string) => void;
  onResizeColumn: (columnId: string, width: number) => void;
  onDuplicateElement: (columnId: string, elementId: string) => void;
  onDeleteElement: (columnId: string, elementId: string) => void;
  onNavigatePage?: (pageId: string) => void;
};

export default function TreeSectionRenderer({ sectionId, columns, pages, device, selectedElementId, onSelectElement, onUpdateElement, onResizeColumn, onDuplicateElement, onDeleteElement, onNavigatePage }: Props) {
  return <div className="grid grid-cols-12 gap-3 p-4" data-section-tree={sectionId}>
    {columns.map((column) => <TreeColumn key={column.id} sectionId={sectionId} column={column} pages={pages} device={device} selectedElementId={selectedElementId} onSelectElement={onSelectElement} onUpdateElement={onUpdateElement} onResizeColumn={onResizeColumn} onDuplicateElement={onDuplicateElement} onDeleteElement={onDeleteElement} onNavigatePage={onNavigatePage} />)}
  </div>;
}

type TreeColumnProps = Omit<Props, 'columns'> & { column: Column };

function TreeColumn({ sectionId, column, pages, device, selectedElementId, onSelectElement, onUpdateElement, onResizeColumn, onDuplicateElement, onDeleteElement, onNavigatePage }: TreeColumnProps) {
  const drop = useDroppable({ id: `column-drop:${sectionId}:${column.id}`, data: { kind: 'column-drop', sectionId, columnId: column.id, index: column.elements.length } });
  const span = device === 'mobile' ? (column.width.mobile || 12) : device === 'tablet' ? (column.width.tablet || column.width.desktop || 12) : (column.width.desktop || 12);
  const style: CSSProperties = { gridColumn: `span ${span} / span ${span}`, minHeight: column.elements.length ? undefined : 96, backgroundColor: column.style.backgroundColor };
  return <div ref={drop.setNodeRef} style={style} className={`relative min-w-0 rounded-xl border-2 border-dashed p-3 pt-9 transition-colors ${drop.isOver ? 'border-pink bg-pink/10' : 'border-black/20'} ${column.elements.length ? 'space-y-3' : 'flex items-center justify-center'}`}>
    <div className="absolute right-2 top-2 z-10 flex items-center gap-1 rounded-lg border border-black/20 bg-white/90 p-1 font-mono text-[9px]" onPointerDown={(event) => event.stopPropagation()}><span className="text-neutral-500">{device}</span><input aria-label={`${device} column width`} type="number" min={1} max={12} value={span} onChange={(event) => onResizeColumn(column.id, Number(event.target.value))} className="w-9 rounded border border-black/20 px-1 text-center"/><span>/ 12</span></div>
    {column.elements.length ? <SortableContext items={column.elements.map((element) => `tree-element:${sectionId}:${column.id}:${element.id}`)} strategy={verticalListSortingStrategy}>{column.elements.map((element, index) => <TreeElement key={element.id} sectionId={sectionId} element={element} pages={pages} device={device} columnId={column.id} index={index} selected={selectedElementId === element.id} onSelect={onSelectElement} onUpdate={onUpdateElement} onDuplicate={onDuplicateElement} onDelete={onDeleteElement} onNavigatePage={onNavigatePage} />)}</SortableContext> : <span className="font-mono text-[10px] font-bold uppercase text-neutral-400">Drop widgets here</span>}
    {drop.isOver && <span className="pointer-events-none rounded-full bg-pink px-3 py-1 font-mono text-[10px] font-bold text-black">Drop here</span>}
  </div>;
}

function TreeElement({ sectionId, element, pages, device, columnId, index, selected, onSelect, onUpdate, onDuplicate, onDelete, onNavigatePage }: { sectionId: string; element: SiteElement; pages: Props['pages']; device: Device; columnId: string; index: number; selected: boolean; onSelect: (columnId: string, elementId: string) => void; onUpdate: Props['onUpdateElement']; onDuplicate: Props['onDuplicateElement']; onDelete: Props['onDeleteElement']; onNavigatePage?: Props['onNavigatePage'] }) {
  const sortable = useSortable({ id: `tree-element:${sectionId}:${columnId}:${element.id}`, data: { kind: 'element', sectionId, columnId, elementId: element.id, index } });
  const resolvedStyle = { ...element.style, ...(device === 'desktop' ? {} : element.responsive?.[device]) };
  const text = typeof element.content.text === 'string' ? element.content.text : typeof element.content.title === 'string' ? element.content.title : '';
  const style: CSSProperties = { ...elementVisualStyle(resolvedStyle), marginLeft: resolvedStyle.textAlign === 'center' ? 'auto' : resolvedStyle.textAlign === 'right' ? 'auto' : resolvedStyle.margin?.left, marginRight: resolvedStyle.textAlign === 'center' ? 'auto' : resolvedStyle.textAlign === 'left' ? 'auto' : resolvedStyle.margin?.right };
  const elementLabel = element.name || element.type.split(/[-_]/g).map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  const [cartOpen, setCartOpen] = useState(false);
  const activateLink = (event: React.MouseEvent<HTMLElement>, href: string) => {
    event.stopPropagation();
    if (href.startsWith('#')) {
      event.preventDefault();
      scrollToAnchor(normalizeAnchorId(href));
      return;
    }
    if (href.startsWith('/')) {
      const requested = href.replace(/^\/+|\/+$/g, '');
      const page = pages.find((entry) => (requested ? entry.id === requested || (entry.slug || '').replace(/^\/+|\/+$/g, '') === requested : entry.isHome));
      if (page && onNavigatePage) { event.preventDefault(); onNavigatePage(page.id); }
    }
  };
  const frame = (child: ReactNode) => <div {...getElementAccessibilityProps(element)} ref={sortable.setNodeRef} style={{ transform: CSS.Transform.toString(sortable.transform), transition: sortable.transition }} className={`group/tree-element relative rounded-lg ${element.customClass || ''} ${sortable.isDragging ? 'z-20 opacity-40' : ''} ${selected ? 'outline outline-2 outline-pink outline-offset-2' : 'hover:outline hover:outline-1 hover:outline-pink/60'}`} data-element-drop={element.id}><button type="button" {...sortable.attributes} {...sortable.listeners} aria-label={`Drag ${elementLabel}`} className="absolute -left-5 top-1 z-10 cursor-grab touch-none p-0.5 text-neutral-400 hover:text-black"><span aria-hidden="true">⠿</span></button><div className="absolute -top-3 right-1 z-10 hidden items-center gap-1 group-hover/tree-element:flex"><button type="button" onClick={(event) => { event.stopPropagation(); onSelect(columnId, element.id); }} className="rounded border border-black bg-yellow px-2 py-0.5 font-mono text-[9px] font-bold">{elementLabel}</button><button type="button" aria-label={`Duplicate ${elementLabel}`} onClick={(event) => { event.stopPropagation(); onDuplicate(columnId, element.id); }} className="rounded border border-black bg-white px-1.5 py-0.5 font-mono text-[9px] font-bold">⧉</button><button type="button" aria-label={`Delete ${elementLabel}`} onClick={(event) => { event.stopPropagation(); onDelete(columnId, element.id); }} className="rounded border border-black bg-white px-1.5 py-0.5 font-mono text-[9px] font-bold">×</button></div><div className={getAnimationClass(resolvedStyle.animation)} onClick={(event) => { event.stopPropagation(); onSelect(columnId, element.id); }}>{child}</div></div>;
  switch (element.type) {
    case 'heading': { const Heading = `h${Math.max(1, Math.min(6, Number(element.content.level) || 2))}` as ElementType; return frame(<Heading style={style} contentEditable suppressContentEditableWarning onInput={(event: React.FormEvent<HTMLElement>) => { const value = event.currentTarget.innerText; onUpdate(columnId, element.id, (current) => ({ ...current, content: { ...current.content, text: value } }), `typing:${element.id}:text`); }} className="text-3xl font-black">{text || 'Your heading'}</Heading>); }
    case 'text': return frame(<p style={style} contentEditable suppressContentEditableWarning onInput={(event) => { const value = event.currentTarget.innerText; onUpdate(columnId, element.id, (current) => ({ ...current, content: { ...current.content, text: value } }), `typing:${element.id}:text`); }} className="min-h-6 whitespace-pre-wrap leading-relaxed">{text || 'Write something for your visitors.'}</p>);
    case 'button': { const target = String(element.content.linkTarget || 'url') as ButtonTarget; const href = resolveButtonHref(target, String(element.content.linkValue || element.content.href || ''), pages); return frame(<a href={href} download={target === 'download' ? String(element.content.downloadName || '') || undefined : undefined} target={element.content.newTab ? '_blank' : undefined} rel={element.content.newTab ? 'noreferrer' : undefined} aria-label={String(element.content.ariaLabel || '') || undefined} onClick={(event) => activateLink(event, href)} style={style} className="inline-flex rounded-xl border-2 border-black bg-yellow px-5 py-3 font-bold shadow-[2px_2px_0_#000]">{text || 'Button label'}</a>); }
    case 'image': return frame(typeof element.content.src === 'string' && element.content.src ? <Image src={element.content.src} alt={element.a11y?.alt || (typeof element.content.alt === 'string' ? element.content.alt : '')} width={1200} height={900} unoptimized style={style} className="max-h-96 w-full rounded-xl object-cover" /> : <div className="flex h-48 items-center justify-center rounded-xl border-2 border-dashed border-black/30 bg-neutral-50 font-mono text-xs text-neutral-500">Select image in properties</div>);
    case 'icon': { const Icon = ({ Star, Heart, Sparkles, Camera } as Record<string, typeof Star>)[String(element.content.icon || 'Star')] || Star; return frame(typeof element.content.src === 'string' && element.content.src ? <Image src={element.content.src} alt={element.a11y?.alt || String(element.content.alt || '')} width={256} height={256} unoptimized style={style} className="h-12 w-12 object-contain" /> : <Icon size={Number(element.content.size || 36)} style={style} />); }
    case 'divider': return frame(<hr style={{ borderColor: resolvedStyle.borderColor || '#111111', borderWidth: resolvedStyle.borderWidth || 1 }} />);
    case 'spacer': return frame(<div style={{ height: Number(element.content.height || 48) }} />);
    case 'video': return frame(typeof element.content.src === 'string' && element.content.src ? <video controls src={element.content.src} className="w-full rounded-xl" /> : <div className="flex h-48 items-center justify-center rounded-xl border-2 border-dashed border-black/30 font-mono text-xs text-neutral-500">Add a video URL in properties</div>);
    case 'gallery': { const images = Array.isArray(element.content.images) ? element.content.images.filter((item): item is string => typeof item === 'string') : []; return frame(<ImageCarousel images={images} carousel={Boolean(element.content.carousel)} autoplay={Boolean(element.content.autoplay)} intervalMs={Number(element.content.intervalMs) || 4000} preview className="w-full" />); }
    case 'form': return frame(<SiteForm id={element.id} content={{ submitLabel: text || element.content.submitLabel || 'Send message', ...element.content }} style={style} className="rounded-xl border border-black/10 bg-white p-4" />);
    case 'html': return frame(<div style={style} className="min-h-8 rounded-lg border border-dashed border-black/20 p-3 font-mono text-xs text-neutral-600">Custom HTML is disabled in the editor preview for safety. Use text and layout elements instead.</div>);
    case 'list': case 'numbered-list': { const items = Array.isArray(element.content.items) ? element.content.items : ['First item', 'Second item']; const List = element.type === 'numbered-list' ? 'ol' : 'ul'; return frame(<List style={style} className={`${element.type === 'numbered-list' ? 'list-decimal' : 'list-disc'} list-inside space-y-1`}>{items.map((item, index) => <li key={index}>{String(item)}</li>)}</List>); }
    case 'quote': return frame(<blockquote style={style} className="border-l-4 border-pink py-2 pl-4 text-xl italic">“{text || 'Add a memorable quote.'}”{Boolean(element.content.attribution) && <cite className="mt-2 block text-sm not-italic">— {String(element.content.attribution)}</cite>}</blockquote>);
    case 'badge': return frame(<span style={style} className="inline-flex rounded-full border border-black/20 bg-yellow px-3 py-1 font-mono text-xs font-bold">{text || 'Badge'}</span>);
    case 'image-caption': return frame(typeof element.content.src === 'string' && element.content.src ? <figure><Image src={element.content.src} alt={element.a11y?.alt || String(element.content.alt || '')} width={1200} height={900} unoptimized className="w-full rounded-xl object-cover"/><figcaption className="mt-2 text-sm text-neutral-600">{String(element.content.caption || 'Image caption')}</figcaption></figure> : <div className="flex h-48 items-center justify-center rounded-xl border-2 border-dashed border-black/30 font-mono text-xs text-neutral-500">Upload an image in properties</div>);
    case 'anchor': return frame(<div className="rounded border border-dashed border-black/20 px-2 py-1 font-mono text-[9px] text-neutral-500">Anchor · #{element.anchorId || String(element.content.id || 'set-an-id')}</div>);
    case 'accordion': { const items = Array.isArray(element.content.items) ? element.content.items as Array<Record<string, unknown>> : []; return frame(<div className="divide-y divide-black/15">{items.map((item, itemIndex) => <details key={itemIndex} className="py-3"><summary className="cursor-pointer font-bold">{String(item.title || `Question ${itemIndex + 1}`)}</summary><p className="mt-2 text-sm">{String(item.description || '')}</p></details>)}</div>); }
    case 'tabs': { const items = Array.isArray(element.content.items) ? element.content.items as Array<Record<string, unknown>> : []; return frame(<TabWidget items={items}/>); }
    case 'social-links': { const items = Array.isArray(element.content.items) ? element.content.items as Array<Record<string, unknown>> : []; return frame(<div className="flex flex-wrap gap-3">{items.map((item, itemIndex) => <a key={itemIndex} href={String(item.url || '#')} onClick={(event) => event.preventDefault()} className="font-bold underline">{String(item.title || `Social ${itemIndex + 1}`)}</a>)}</div>); }
    case 'card': return frame(<article style={style} className="rounded-xl border-2 border-black bg-white p-5 shadow-[2px_2px_0_#000]"><h3 className="font-bold">{String(element.content.title || 'Card title')}</h3><p className="mt-2 text-sm">{String(element.content.description || 'Add a short description.')}</p></article>);
    case 'block': {
      const blockType = String(element.content.blockType || '');
      const blockLabel = getEditorCatalogItem(blockType)?.label || String(element.content.title || element.name || 'Element');
      const widget = getEditorWidgetDefinition(blockType);
      if (widget) return frame(<CatalogWidgetPreview kind={widget.kind} widgetId={widget.id} content={element.content} style={style} isEditor onChange={(key, value, historyGroup) => onUpdate(columnId, element.id, (current) => ({ ...current, content: { ...current.content, [key]: value } }), historyGroup)} />);
      const catalogItem = getEditorCatalogItem(blockType);
      const normalized = `${blockType} ${blockLabel}`.toLowerCase();
      const blockItems = Array.isArray(element.content.items) ? element.content.items as Array<Record<string, unknown>> : [];
      const actionLabel = String(element.content.buttonText || element.content.cta || '').trim();
      const actionTarget = String(element.content.linkTarget || 'url') as ButtonTarget;
      const rawActionHref = String(element.content.linkValue || element.content.href || '').trim();
      const actionHref = resolveButtonHref(actionTarget, rawActionHref, pages);
      const editable = (key: string, value: string, className: string) => <span contentEditable suppressContentEditableWarning onInput={(event) => { const next = event.currentTarget.textContent || ''; onUpdate(columnId, element.id, (current) => ({ ...current, content: { ...current.content, [key]: next } }), `typing:${element.id}:${key}`); }} className={className}>{value}</span>;
      if (/cart|shopping bag|mini cart|cart drawer|cart modal/.test(normalized)) {
        const cartItems = blockItems.length ? blockItems : [{ title: 'Sample product', description: 'Add products from your store to see them here.', price: '₹1,499', quantity: 1 }];
        const subtotal = cartItems.reduce((total, item) => total + (Number(String(item.price || '').replace(/[^\d.]/g, '')) || 0) * (Number(item.quantity) || 1), 0);
        return frame(<div style={style} className="relative rounded-2xl border-2 border-black bg-white p-4 shadow-[3px_3px_0_#000]"><div className="flex items-center justify-between gap-3"><div><h3 className="font-display text-lg font-black">{editable('title', String(element.content.title || 'Your cart'), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><p className="text-xs text-neutral-500">{cartItems.length} item{cartItems.length === 1 ? '' : 's'} · ₹{subtotal.toLocaleString('en-IN')}</p></div><button type="button" onClick={() => setCartOpen(true)} className="rounded-lg border-2 border-black bg-yellow px-3 py-2 text-xs font-bold">{actionLabel || 'Open cart'}</button></div>{cartOpen && <div className="fixed inset-0 z-[160] flex items-center justify-center bg-black/45 p-4" role="dialog" aria-modal="true" aria-label="Cart preview" onMouseDown={(event) => { if (event.target === event.currentTarget) setCartOpen(false); }}><div className="w-full max-w-md rounded-2xl border-2 border-black bg-white p-5 text-black shadow-[5px_5px_0_#000]"><div className="flex items-center justify-between"><h4 className="text-xl font-black">Cart preview</h4><button type="button" onClick={() => setCartOpen(false)} aria-label="Close cart" className="rounded border border-black px-2 py-1 font-bold">×</button></div><ul className="mt-4 divide-y divide-black/10">{cartItems.map((item, index) => <li key={index} className="flex justify-between gap-3 py-3 text-sm"><span>{String(item.title || item.name || `Item ${index + 1}`)} × {Number(item.quantity) || 1}</span><strong>{String(item.price || '—')}</strong></li>)}</ul><div className="mt-3 flex justify-between border-t border-black/10 pt-3 font-bold"><span>Subtotal</span><span>₹{subtotal.toLocaleString('en-IN')}</span></div><button type="button" onClick={() => setCartOpen(false)} className="mt-4 w-full rounded-lg border-2 border-black bg-yellow px-4 py-2 font-bold">Continue shopping</button></div></div>}</div>);
      }
      if (catalogItem?.category === 'navigation' || /sidebar menu|navbar|navigation menu|mega menu|dropdown menu|flyout menu|footer menu|mobile menu|link tree|sitemap|breadcrumbs|scrollspy/.test(normalized)) {
        const configured: Array<Record<string, unknown>> = blockItems.length ? blockItems : pages.map((page) => ({ title: page.title, href: page.slug ? `/${page.slug.replace(/^\//, '')}` : '/' }));
        const vertical = normalized.includes('sidebar') || normalized.includes('footer');
        return frame(<nav aria-label={String(element.content.title || blockLabel)} style={style} className={`rounded-xl border border-black/15 bg-white p-4 ${vertical ? 'max-w-xs' : 'overflow-x-auto'}`}><p className="mb-3 font-mono text-[10px] font-black uppercase tracking-wider text-neutral-500">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</p><ul className={vertical ? 'space-y-1' : 'flex min-w-max items-center gap-2'}>{configured.map((item, index) => { const href = String(item.href || item.url || '#'); const safeHref = /^(https?:\/\/|mailto:|tel:|\/|#)/i.test(href) ? href : '#'; return <li key={index}><a href={safeHref} onClick={(event) => activateLink(event, safeHref)} className={`block rounded-lg px-3 py-2 text-sm font-semibold transition-colors hover:bg-yellow ${vertical ? 'w-full' : 'whitespace-nowrap'}`}>{String(item.title || item.label || `Page ${index + 1}`)}</a></li>; })}</ul></nav>);
      }
      if (normalized.includes('faq') || normalized.includes('accordion')) return frame(<section style={style} className="mx-auto max-w-3xl py-4"><h3 className="mb-5 text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><div className="divide-y divide-black/15 border-y border-black/15">{blockItems.map((item, index) => <details key={index} className="group py-4" open={index === 0}><summary className="cursor-pointer list-none pr-8 font-bold marker:hidden">{String(item.title || `Question ${index + 1}`)}<span aria-hidden="true" className="float-right transition-transform group-open:rotate-45">＋</span></summary><p className="mt-3 leading-relaxed text-neutral-600">{String(item.description || item.answer || 'Add a helpful answer.')}</p></details>)}</div></section>);
      if (normalized.includes('pricing') || normalized.includes('plan comparison')) return frame(<section style={style} className="py-5"><h3 className="text-center text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3>{Boolean(element.content.description) && <p className="mx-auto mt-2 max-w-2xl text-center text-neutral-600">{editable('description', String(element.content.description), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</p>}<div className="mt-6 grid gap-4 md:grid-cols-3">{blockItems.map((item, index) => <article key={index} className={`rounded-2xl border-2 p-5 ${item.highlighted ? 'border-black bg-yellow shadow-[4px_4px_0_#000]' : 'border-black/15 bg-white'}`}><h4 className="text-lg font-black">{String(item.title || `Plan ${index + 1}`)}</h4><p className="mt-3 text-3xl font-black">{String(item.price || 'Contact us')}<small className="ml-1 text-xs font-normal">{String(item.interval || '')}</small></p><p className="mt-2 text-sm text-neutral-600">{String(item.description || '')}</p><ul className="mt-4 space-y-2 text-sm">{(Array.isArray(item.features) ? item.features : []).map((feature, featureIndex) => <li key={featureIndex}>✓ {String(feature)}</li>)}</ul><a href={String(item.href || '#contact')} className="mt-5 inline-flex rounded-lg border-2 border-black bg-white px-4 py-2 text-sm font-bold">{String(item.buttonText || 'Choose plan')}</a></article>)}</div></section>);
      if (normalized.includes('testimonial') || normalized.includes('review')) return frame(<section style={style} className="py-5"><h3 className="text-center text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><div className="mt-6 grid gap-4 md:grid-cols-2">{blockItems.map((item, index) => <figure key={index} className="rounded-2xl border-2 border-black/15 bg-white p-5"><div aria-label={`${Number(item.rating || 5)} out of 5 stars`} className="text-lg text-amber-500">{'★'.repeat(Math.max(1, Math.min(5, Number(item.rating || 5))))}</div><blockquote className="mt-3 leading-relaxed">“{String(item.quote || item.description || item.desc || 'Add a customer quote.') }”</blockquote><figcaption className="mt-4 border-t border-black/10 pt-3"><strong>{String(item.name || item.title || `Customer ${index + 1}`)}</strong>{Boolean(item.role) && <span className="ml-2 text-sm text-neutral-500">{String(item.role)}</span>}</figcaption></figure>)}</div></section>);
      if (normalized.includes('stat') || normalized.includes('counter') || normalized.includes('kpi')) return frame(<section style={style} className="py-5"><h3 className="text-center text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><div className="mt-6 grid grid-cols-1 gap-4 sm:grid-cols-3">{blockItems.map((item, index) => <article key={index} className="rounded-2xl border-2 border-black/15 bg-white p-5 text-center"><p className="text-3xl font-black text-pink-600">{String(item.value || item.number || '0')}</p><p className="mt-1 font-mono text-xs uppercase tracking-wide text-neutral-500">{String(item.label || item.title || `Result ${index + 1}`)}</p></article>)}</div></section>);
      if (normalized.includes('timeline') || normalized.includes('steps') || normalized.includes('process')) return frame(<section style={style} className="py-5"><h3 className="text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><ol className="mt-5 space-y-4 border-l-2 border-pink pl-5">{blockItems.map((item, index) => <li key={index} className="relative rounded-xl border border-black/10 bg-white p-4 before:absolute before:-left-[1.65rem] before:top-5 before:h-3 before:w-3 before:rounded-full before:border-2 before:border-black before:bg-yellow"><span className="font-mono text-[10px] font-bold uppercase text-neutral-500">{String(item.date || `Step ${index + 1}`)}</span><h4 className="mt-1 font-bold">{String(item.title || item.name || 'Milestone')}</h4><p className="mt-1 text-sm text-neutral-600">{String(item.description || item.desc || '')}</p></li>)}</ol></section>);
      if (/product|shop|catalog|store/.test(normalized)) return frame(<section style={style} className="py-5"><h3 className="text-2xl font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3>{Boolean(element.content.description) && <p className="mt-2 max-w-2xl text-neutral-600">{editable('description', String(element.content.description), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</p>}<div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{blockItems.map((item, index) => { const href = String(item.href || ''); const safeHref = /^(https?:\/\/|\/|#)/i.test(href) ? href : '#'; return <article id={`product-${index + 1}`} key={index} className="overflow-hidden rounded-2xl border-2 border-black/15 bg-white"><a href={safeHref} onClick={(event) => event.preventDefault()} className="block aspect-[4/3] overflow-hidden bg-gradient-to-br from-yellow/35 via-pink/15 to-emerald-100">{typeof (item.image || item.src) === 'string' && (item.image || item.src) ? <Image src={String(item.image || item.src)} alt={String(item.alt || item.title || '')} width={900} height={700} unoptimized className="h-full w-full object-cover"/> : <span aria-hidden="true" className="flex h-full items-center justify-center font-display text-5xl font-black text-black/25">{String(index + 1).padStart(2, '0')}</span>}</a><div className="p-4">{Boolean(item.category) && <p className="font-mono text-[9px] font-bold uppercase tracking-widest text-neutral-500">{String(item.category)}</p>}<h4 className="mt-1 font-bold">{String(item.title || item.name || `Product ${index + 1}`)}</h4>{Boolean(item.description || item.desc) && <p className="mt-1 text-sm leading-relaxed text-neutral-600">{String(item.description || item.desc)}</p>}<div className="mt-4 flex items-center justify-between gap-3"><strong>{String(item.price || 'Add price')}</strong>{actionLabel && actionHref ? <a href={actionHref} onClick={(event) => event.preventDefault()} className="rounded-lg border-2 border-black bg-yellow px-3 py-2 text-xs font-bold">{actionLabel}</a> : <span className="rounded-lg border border-black/15 px-3 py-2 text-xs font-bold">Add action in properties</span>}</div></div></article>; })}</div></section>);
      if (/map|embed|iframe|calendar|instagram|twitter|social feed/.test(normalized) && typeof element.content.url === 'string' && /^https:\/\//i.test(element.content.url)) return frame(<section style={style} className="overflow-hidden rounded-xl border-2 border-black/15 bg-white"><h3 className="p-4 font-bold">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><iframe title={String(element.content.title || blockLabel)} src={element.content.url} loading="lazy" sandbox="allow-scripts allow-forms allow-presentation" referrerPolicy="no-referrer" className="h-72 w-full border-t border-black/10"/></section>);
      if (/audio|podcast/.test(normalized) && typeof element.content.url === 'string' && element.content.url) return frame(<section style={style} className="rounded-xl border-2 border-black/15 bg-white p-4"><h3 className="mb-3 font-bold">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3><audio controls preload="none" src={element.content.url} className="w-full">Your browser does not support audio playback.</audio></section>);
      if (normalized.includes('skill bar') || normalized.includes('progress bar')) return frame(<article style={style} className="rounded-2xl border-2 border-black/15 bg-white p-5"><h3 className="font-display text-lg font-black">{editable('title', String(element.content.title || blockLabel), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</h3>{Boolean(element.content.description) && <p className="mt-1 text-sm text-neutral-600">{editable('description', String(element.content.description), 'outline-none focus-visible:ring-2 focus-visible:ring-pink')}</p>}<div className="mt-5 space-y-4">{blockItems.map((item, index) => { const value = Math.max(0, Math.min(100, Number(item.value ?? item.percent ?? 70))); return <div key={index}><div className="mb-1 flex items-center justify-between gap-3 text-sm font-semibold"><span>{String(item.title || item.label || `Skill ${index + 1}`)}</span><span className="font-mono text-xs text-neutral-500">{value}%</span></div><div role="progressbar" aria-label={String(item.title || item.label || `Skill ${index + 1}`)} aria-valuemin={0} aria-valuemax={100} aria-valuenow={value} className="h-2.5 overflow-hidden rounded-full bg-neutral-100"><div className="h-full rounded-full bg-pink" style={{ width: `${value}%` }}/></div></div>; })}</div></article>);
      const advanced = <CatalogBlockRenderer normalized={normalized} blockLabel={blockLabel} element={element} items={blockItems} style={style} actionLabel={actionLabel} actionHref={actionHref} onUpdate={(update, historyGroup) => onUpdate(columnId, element.id, update, historyGroup)} onNavigate={(event, href) => activateLink(event, href)} />;
      return frame(advanced);
    }
    default: {
      if (supportsAdditionalElement(element.type)) {
        return frame(<SiteElementPreview
          element={element}
          style={style}
          isEditor
          onChange={(key, value, historyGroup) => onUpdate(columnId, element.id, (current) => ({
            ...current,
            content: { ...current.content, [key]: value },
          }), historyGroup)}
        />);
      }
      const fallbackTitle = text || element.name || element.type.replace(/[-_]/g, ' ');
      const fallbackDescription = typeof element.content.description === 'string'
        ? element.content.description
        : 'Customize this element in the Content and Style tabs.';
      return frame(<article style={style} className="rounded-xl border-2 border-dashed border-black/30 bg-white p-4">
        <h3 className="font-display text-lg font-black capitalize">{fallbackTitle}</h3>
        <p className="mt-1 text-sm text-neutral-600">{fallbackDescription}</p>
        <p className="mt-3 font-mono text-[9px] font-bold uppercase tracking-wide text-neutral-400">{element.type} · content and style ready</p>
      </article>);
    }
  }
}

type CatalogBlockProps = {
  normalized: string;
  blockLabel: string;
  element: SiteElement;
  items: Array<Record<string, unknown>>;
  style: CSSProperties;
  actionLabel: string;
  actionHref: string;
  onUpdate: (update: (element: SiteElement) => SiteElement, historyGroup?: string) => void;
  onNavigate: (event: React.MouseEvent<HTMLElement>, href: string) => void;
};

function CatalogBlockRenderer({ normalized, blockLabel, element, items, style, actionLabel, actionHref, onUpdate, onNavigate }: CatalogBlockProps) {
  const [open, setOpen] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [toggle, setToggle] = useState(false);
  const [step, setStep] = useState(0);
  const [comparison, setComparison] = useState(50);
  const [seconds, setSeconds] = useState(Math.max(0, Number(element.content.seconds || 86400)));
  useEffect(() => {
    if (!normalized.includes('countdown')) return;
    const timer = window.setInterval(() => setSeconds((value) => value > 0 ? value - 1 : 0), 1000);
    return () => window.clearInterval(timer);
  }, [normalized]);
  const title = String(element.content.title || blockLabel);
  const description = String(element.content.description || 'Add useful content for your visitors.');
  const safeItems = items.length ? items : [{ title: 'First item', description: 'Add a clear detail here.', image: '' }, { title: 'Second item', description: 'Add another useful detail.', image: '' }];
  const updateContent = (key: string, value: unknown, historyGroup?: string) => onUpdate((current) => ({ ...current, content: { ...current.content, [key]: value } }), historyGroup);
  const editable = (key: string, value: string, className = 'outline-none focus-visible:ring-2 focus-visible:ring-pink') => <span contentEditable suppressContentEditableWarning onInput={(event) => updateContent(key, event.currentTarget.textContent || '', `typing:${element.id}:${key}`)} className={className}>{value}</span>;
  const safeHref = /^(https?:\/\/|mailto:|tel:|\/|#)/i.test(actionHref) ? actionHref : '#';
  const image = (item: Record<string, unknown>, index: number, className = 'h-40 w-full object-cover') => typeof (item.image || item.src || item.url) === 'string' && (item.image || item.src || item.url) ? <Image src={String(item.image || item.src || item.url)} alt={String(item.alt || item.title || `Image ${index + 1}`)} width={900} height={600} unoptimized className={className} /> : <div className={`${className} flex items-center justify-center bg-gradient-to-br from-yellow/40 via-pink/20 to-emerald-100 text-3xl font-black text-black/30`} aria-hidden="true">{String(index + 1).padStart(2, '0')}</div>;
  const button = (label: string, href = safeHref, extra?: string) => <a href={href} onClick={(event) => onNavigate(event, href)} className={`inline-flex items-center justify-center rounded-lg border-2 border-black bg-yellow px-4 py-2 text-sm font-bold shadow-[2px_2px_0_#000] ${extra || ''}`}>{label} <span aria-hidden="true" className="ml-2">↗</span></a>;
  const renderForm = (kind: string) => <form onSubmit={(event) => { event.preventDefault(); setSubmitted(true); }} className="grid gap-3 rounded-2xl border-2 border-black bg-white p-5 shadow-[3px_3px_0_#000]" aria-label={title}><h3 className="text-xl font-black">{editable('title', title)}</h3><p className="text-sm text-neutral-600">{editable('description', description)}</p>{kind === 'survey' ? <label className="grid gap-1 text-sm font-semibold">How helpful was this?<select className="rounded-lg border-2 border-black p-2" defaultValue="5"><option>5 — Excellent</option><option>4 — Good</option><option>3 — Okay</option><option>2 — Needs work</option><option>1 — Poor</option></select></label> : <><label className="grid gap-1 text-sm font-semibold">Name<input required={!/newsletter|search/.test(kind)} name="name" className="rounded-lg border-2 border-black p-2" placeholder="Your name" /></label><label className="grid gap-1 text-sm font-semibold">Email<input required name="email" type="email" className="rounded-lg border-2 border-black p-2" placeholder="you@example.com" /></label><label className="grid gap-1 text-sm font-semibold">Message<textarea name="message" className="min-h-20 rounded-lg border-2 border-black p-2" placeholder="How can we help?" /></label>{kind === 'advanced' && <div className="grid gap-2 sm:grid-cols-2"><label className="text-sm font-semibold">Date<input type="date" className="mt-1 w-full rounded-lg border-2 border-black p-2" /></label><label className="text-sm font-semibold">Rating<input type="range" min="1" max="5" className="mt-3 w-full" /></label></div>}</>}<button type="submit" className="rounded-lg border-2 border-black bg-pink px-4 py-2 font-bold">{kind === 'newsletter' ? 'Subscribe' : kind === 'search' ? 'Search' : 'Submit'}</button>{submitted && <p role="status" className="rounded-lg bg-emerald-100 p-2 text-sm font-bold">Thanks — this demo submission was received.</p>}</form>;

  if (/advanced form|booking|appointment|auth|login|signup|survey|quiz|multi-step|newsletter popup|newsletter form|search bar|form inbox|submissions/.test(normalized)) return <div style={style}>{normalized.includes('multi-step') ? <div className="rounded-2xl border-2 border-black bg-white p-5"><div className="mb-4 flex items-center justify-between font-mono text-xs font-bold uppercase"><span>Step {step + 1} of 3</span><span>{Math.round(((step + 1) / 3) * 100)}%</span></div>{step === 0 ? renderForm('advanced') : step === 1 ? <div className="rounded-xl bg-neutral-50 p-5"><h3 className="font-black">Preferences</h3><label className="mt-3 flex items-center gap-2"><input type="checkbox" defaultChecked /> Send me helpful updates</label><label className="mt-3 flex items-center gap-2"><input type="checkbox" /> Add a calendar reminder</label></div> : <div className="rounded-xl bg-emerald-50 p-5"><h3 className="font-black">Review and finish</h3><p className="mt-2 text-sm">Everything is ready to submit.</p></div>}<div className="mt-4 flex justify-between gap-2"><button type="button" disabled={step === 0} onClick={() => setStep((value) => Math.max(0, value - 1))} className="rounded-lg border-2 border-black bg-white px-4 py-2 font-bold disabled:opacity-40">Back</button><button type="button" onClick={() => setStep((value) => Math.min(2, value + 1))} className="rounded-lg border-2 border-black bg-yellow px-4 py-2 font-bold">{step === 2 ? 'Finish' : 'Next'}</button></div></div> : renderForm(normalized.includes('newsletter') ? 'newsletter' : normalized.includes('search') ? 'search' : normalized.includes('survey') || normalized.includes('quiz') ? 'survey' : 'advanced')}</div>;
  if (/button group|download button|back to top|floating action/.test(normalized)) return <div style={style} className="flex flex-wrap items-center gap-3">{safeItems.slice(0, 4).map((item, index) => { const label = String(item.title || item.label || (index === 0 ? actionLabel || blockLabel : `Action ${index + 1}`)); const href = String(item.href || item.url || safeHref); return /download/.test(normalized) ? <a key={index} href={href} download className="rounded-lg border-2 border-black bg-yellow px-4 py-2 font-bold">{label} ↓</a> : /back to top/.test(normalized) ? <button key={index} type="button" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })} className="rounded-lg border-2 border-black bg-yellow px-4 py-2 font-bold">{label || 'Back to top'} ↑</button> : /floating action/.test(normalized) ? <button key={index} type="button" onClick={() => window.alert(String(item.description || 'Action ready to configure.'))} className="fixed bottom-5 right-5 z-30 rounded-full border-2 border-black bg-pink px-5 py-3 font-bold shadow-[3px_3px_0_#000]">{label}</button> : button(label, href); })}</div>;
  if (/typewriter|marquee|ticker/.test(normalized)) return <div style={{ ...style, overflow: 'hidden' }} className="rounded-xl border-2 border-black bg-black px-5 py-4 font-mono font-bold text-yellow"><span className={normalized.includes('typewriter') ? 'inline-block animate-pulse' : 'inline-block whitespace-nowrap motion-safe:animate-[marquee_18s_linear_infinite]'}>{editable('text', String(element.content.text || title))}</span></div>;
  if (/code block|code/.test(normalized)) return <pre style={style} className="overflow-x-auto rounded-xl border-2 border-black bg-[#111827] p-5 font-mono text-sm text-emerald-200"><code contentEditable suppressContentEditableWarning onInput={(event) => updateContent('code', event.currentTarget.textContent || '')}>{String(element.content.code || 'const launch = () => “create something great”;')}</code></pre>;
  if (/table of contents/.test(normalized)) return <nav style={style} className="rounded-xl border-2 border-black bg-white p-5"><h3 className="font-black">{editable('title', title)}</h3><ol className="mt-3 list-decimal space-y-2 pl-5 text-sm">{safeItems.map((item, index) => <li key={index}><a href={`#${String(item.anchor || item.id || `section-${index + 1}`)}`} onClick={(event) => onNavigate(event, `#${String(item.anchor || item.id || `section-${index + 1}`)}`)} className="font-semibold underline">{String(item.title || `Section ${index + 1}`)}</a></li>)}</ol></nav>;
  if (/table/.test(normalized) && !/table of contents/.test(normalized)) return <div style={style} className="overflow-x-auto rounded-xl border-2 border-black bg-white"><table className="w-full text-left text-sm"><caption className="p-4 text-left text-lg font-black">{editable('title', title)}</caption><thead className="bg-yellow"><tr><th className="p-3">Item</th><th className="p-3">Details</th><th className="p-3">Status</th></tr></thead><tbody>{safeItems.map((item, index) => <tr key={index} className="border-t border-black/10"><td className="p-3 font-bold">{String(item.title || `Row ${index + 1}`)}</td><td className="p-3">{String(item.description || item.value || 'Add details')}</td><td className="p-3">{String(item.status || 'Active')}</td></tr>)}</tbody></table></div>;
  if (/before\s*after/.test(normalized)) return <div style={style} className="relative overflow-hidden rounded-2xl border-2 border-black bg-neutral-100"><div className="grid min-h-64 place-items-center bg-gradient-to-br from-pink/30 to-emerald-200 font-black text-black/40">AFTER</div><div className="absolute inset-y-0 left-0 grid place-items-center overflow-hidden bg-gradient-to-br from-yellow/60 to-pink/40 font-black text-black/50" style={{ width: `${comparison}%` }}><span className="min-w-[24rem] text-center">BEFORE</span></div><input aria-label="Before and after position" type="range" min="0" max="100" value={comparison} onChange={(event) => setComparison(Number(event.target.value))} className="absolute inset-x-4 bottom-4 z-10" /></div>;
  if (/carousel gallery|masonry gallery|logo carousel|avatar group|gallery/.test(normalized)) { const galleryImages = safeItems.map((item) => String(item.image || item.src || item.url || '')).filter(Boolean); return <div style={style} className="rounded-2xl border-2 border-black bg-white p-4"><div className="mb-3 flex items-end justify-between gap-3"><div><h3 className="text-xl font-black">{editable('title', title)}</h3><p className="text-sm text-neutral-600">{editable('description', description)}</p></div>{/masonry/.test(normalized) && <span className="rounded-full bg-yellow px-2 py-1 font-mono text-[10px] font-bold">MASONRY</span>}</div>{galleryImages.length ? <ImageCarousel images={galleryImages} carousel={/carousel|logo/.test(normalized)} autoplay={/carousel/.test(normalized)} intervalMs={3500} preview className={/masonry/.test(normalized) ? 'columns-2 gap-3 space-y-3' : 'w-full'} /> : <div className="grid grid-cols-2 gap-3 md:grid-cols-4">{safeItems.map((item, index) => <div key={index} className="overflow-hidden rounded-xl border border-black/10">{image(item, index, 'h-28 w-full object-cover')}<p className="p-2 text-xs font-bold">{String(item.title || `Image ${index + 1}`)}</p></div>)}</div>}</div>; }
  if (/video hero|background video/.test(normalized)) return <section style={{ ...style, position: 'relative', overflow: 'hidden' }} className="min-h-64 rounded-2xl border-2 border-black bg-black text-white"><video className="absolute inset-0 h-full w-full object-cover opacity-60" src={String(element.content.url || element.content.src || '')} muted autoPlay loop playsInline /><div className="relative z-10 grid min-h-64 place-items-center bg-black/30 p-8 text-center"><div><p className="font-mono text-xs uppercase tracking-widest text-yellow">{editable('eyebrow', String(element.content.eyebrow || 'Featured story'))}</p><h3 className="mt-2 text-4xl font-black">{editable('title', title)}</h3><p className="mx-auto mt-3 max-w-xl text-white/80">{editable('description', description)}</p>{actionLabel && <div className="mt-5">{button(actionLabel)}</div>}</div></div></section>;
  if (/audio|podcast/.test(normalized)) return <div style={style} className="rounded-2xl border-2 border-black bg-white p-5"><h3 className="font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p><label className="mt-4 block font-mono text-[10px] font-bold uppercase">Audio URL<input value={String(element.content.url || element.content.src || '')} onChange={(event) => updateContent('url', event.target.value)} className="mt-1 w-full rounded-lg border-2 border-black px-3 py-2 font-sans text-sm font-normal normal-case" placeholder="https://…/episode.mp3" /></label>{String(element.content.url || element.content.src || '') ? <audio className="mt-4 w-full" controls src={String(element.content.url || element.content.src)} /> : <div className="mt-4 rounded-lg border border-dashed border-black/30 p-4 text-center text-sm text-neutral-500">Add an audio URL to enable playback.</div>}</div>;
  if (/map|calendar|instagram|twitter|social feed|youtube|vimeo|video embed/.test(normalized)) return <div style={style} className="overflow-hidden rounded-2xl border-2 border-black bg-white"><div className="p-5"><h3 className="font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p><label className="mt-4 block font-mono text-[10px] font-bold uppercase">Embed URL<input value={String(element.content.url || element.content.src || '')} onChange={(event) => updateContent('url', event.target.value)} className="mt-1 w-full rounded-lg border-2 border-black px-3 py-2 font-sans text-sm font-normal normal-case" placeholder="https://…" /></label></div>{/^https:\/\//i.test(String(element.content.url || element.content.src || '')) ? <iframe title={title} src={String(element.content.url || element.content.src)} loading="lazy" sandbox="allow-scripts allow-forms allow-presentation" referrerPolicy="no-referrer" className="h-64 w-full border-t border-black/10" /> : <div className="mx-5 mb-5 grid h-48 place-items-center rounded-xl bg-gradient-to-br from-yellow/30 via-pink/20 to-emerald-100 font-mono text-xs text-neutral-500">Paste a secure HTTPS embed URL to preview this content.</div>}</div>;
  if (/lottie|svg image|image crop|stock photo|image editing/.test(normalized)) return <div style={style} className="rounded-2xl border-2 border-black bg-white p-4"><h3 className="font-black">{editable('title', title)}</h3>{image({ src: String(element.content.url || element.content.src || '') }, 0, 'mt-3 h-48 w-full rounded-xl object-contain bg-neutral-50')}<p className="mt-2 text-xs text-neutral-500">Set the source URL and focal position in the Content and Style inspector.</p></div>;
  if (/language switcher/.test(normalized)) return <label style={style} className="inline-flex items-center gap-2 rounded-xl border-2 border-black bg-white px-3 py-2 text-sm font-bold"><span>{editable('title', title)}</span><select className="rounded border border-black p-1" defaultValue="en"><option value="en">English</option><option value="hi">हिन्दी</option><option value="fr">Français</option></select></label>;
  if (/pagination/.test(normalized)) return <nav style={style} aria-label="Pagination" className="flex flex-wrap items-center gap-2">{[1, 2, 3, 4].map((page) => <button key={page} type="button" className={`rounded-lg border-2 border-black px-3 py-2 font-bold ${page === 1 ? 'bg-yellow' : 'bg-white'}`}>{page}</button>)}<button type="button" className="rounded-lg border-2 border-black bg-white px-3 py-2 font-bold">Next →</button></nav>;
  if (/tabs container|deep-link tabs/.test(normalized)) return <div style={style}><TabWidget items={safeItems}/></div>;
  if (/category tiles|bundle builder|gift card|size guide|delivery slot|recently viewed|wishlist|compare products|product/.test(normalized)) return <section style={style} className="rounded-2xl border-2 border-black bg-white p-5"><div className="flex items-start justify-between gap-4"><div><h3 className="text-2xl font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p></div>{/gift card/.test(normalized) && <span className="rounded-full bg-pink px-3 py-1 text-xs font-black">GIFT READY</span>}</div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{safeItems.map((item, index) => <article key={index} className="overflow-hidden rounded-xl border-2 border-black/15 bg-neutral-50">{image(item, index)}<div className="p-3"><h4 className="font-black">{String(item.title || `Option ${index + 1}`)}</h4><p className="mt-1 text-sm text-neutral-600">{String(item.description || item.desc || 'Add product details.')}</p><div className="mt-3 flex items-center justify-between gap-2"><strong>{String(item.price || '₹999')}</strong><button type="button" onClick={() => setSubmitted(true)} className="rounded-lg border-2 border-black bg-yellow px-3 py-1.5 text-xs font-bold">{/wishlist|recently/.test(normalized) ? 'Save' : /compare/.test(normalized) ? 'Compare' : 'Add'}</button></div></div></article>)}</div>{submitted && <p className="mt-3 rounded-lg bg-emerald-100 p-2 text-sm font-bold" role="status">Saved to your demo store state.</p>}</section>;
  if (/portfolio grid|case study|project detail|author box|related posts|blog|post|comments|rss/.test(normalized)) return <section style={style} className="rounded-2xl border-2 border-black bg-white p-5"><div className="flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] font-bold uppercase tracking-widest text-pink-600">{String(element.content.category || 'Story')}</p><h3 className="mt-1 text-2xl font-black">{editable('title', title)}</h3><p className="mt-2 max-w-2xl text-neutral-600">{editable('description', description)}</p></div>{/rss/.test(normalized) ? <a href="/rss.xml" className="rounded-lg border-2 border-black bg-yellow px-3 py-2 text-sm font-bold">RSS ↗</a> : /comments/.test(normalized) ? <button type="button" onClick={() => setOpen(true)} className="rounded-lg border-2 border-black bg-yellow px-3 py-2 text-sm font-bold">Join discussion</button> : null}</div><div className="mt-5 grid gap-3 md:grid-cols-2">{safeItems.map((item, index) => <article key={index} className="overflow-hidden rounded-xl border border-black/15">{image(item, index)}<div className="p-4"><h4 className="font-black">{String(item.title || `Story ${index + 1}`)}</h4><p className="mt-1 text-sm text-neutral-600">{String(item.description || item.quote || 'A useful story for your audience.')}</p><p className="mt-3 font-mono text-xs text-neutral-500">{String(item.author || 'Launchly editorial')} · 5 min read</p></div></article>)}</div>{open && <div className="mt-4 rounded-xl border-2 border-black bg-yellow/30 p-4"><textarea className="min-h-20 w-full rounded-lg border-2 border-black p-2" placeholder="Write a comment…"/><button type="button" onClick={() => { setOpen(false); setSubmitted(true); }} className="mt-2 rounded-lg border-2 border-black bg-black px-4 py-2 font-bold text-white">Post comment</button></div>}</section>;
  if (/modal|popup|exit popup|cookie banner|chat widget/.test(normalized)) return <div style={style} className="rounded-2xl border-2 border-black bg-white p-5"><h3 className="text-xl font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p><button type="button" onClick={() => setOpen(true)} className="mt-4 rounded-lg border-2 border-black bg-pink px-4 py-2 font-bold">{/chat widget/.test(normalized) ? 'Open chat' : 'Open preview'}</button>{open && <div className="fixed inset-0 z-[150] grid place-items-center bg-black/50 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-2xl border-2 border-black bg-white p-6 shadow-[5px_5px_0_#000]"><div className="flex items-center justify-between"><h4 className="text-xl font-black">{title}</h4><button type="button" onClick={() => setOpen(false)} aria-label="Close dialog" className="rounded border-2 border-black px-2 py-1 font-bold">×</button></div><p className="mt-3 text-sm text-neutral-600">{description}</p>{/cookie banner|newsletter popup/.test(normalized) ? <form onSubmit={(event) => { event.preventDefault(); setSubmitted(true); }} className="mt-4 flex gap-2"><input type="email" required placeholder="Email address" className="min-w-0 flex-1 rounded border-2 border-black px-3 py-2"/><button className="rounded border-2 border-black bg-yellow px-3 py-2 font-bold">Join</button></form> : <button type="button" onClick={() => setOpen(false)} className="mt-4 rounded border-2 border-black bg-yellow px-4 py-2 font-bold">Continue</button>}</div></div>}</div>;
  if (/toggle|tooltip/.test(normalized)) return <div style={style} className="flex items-center gap-3 rounded-xl border-2 border-black bg-white p-4"><button type="button" aria-pressed={toggle} onClick={() => setToggle((value) => !value)} className={`relative h-7 w-14 rounded-full border-2 border-black transition-colors ${toggle ? 'bg-emerald-400' : 'bg-neutral-200'}`}><span className={`absolute top-0.5 h-5 w-5 rounded-full border border-black bg-white transition-transform ${toggle ? 'translate-x-7' : 'translate-x-0.5'}`} /></button><span title={/tooltip/.test(normalized) ? description : undefined} className="font-bold">{editable('title', title)} <small className="ml-2 text-neutral-500">{toggle ? 'On' : 'Off'}</small></span></div>;
  if (/countdown/.test(normalized)) return <div style={style} className="rounded-2xl border-2 border-black bg-black p-6 text-center text-white"><p className="font-mono text-xs uppercase tracking-widest text-yellow">{editable('title', title)}</p><p className="mt-2 text-4xl font-black tabular-nums">{String(Math.floor(seconds / 86400)).padStart(2, '0')}:{String(Math.floor((seconds % 86400) / 3600)).padStart(2, '0')}:{String(Math.floor((seconds % 3600) / 60)).padStart(2, '0')}:{String(seconds % 60).padStart(2, '0')}</p><p className="mt-2 text-sm text-white/70">{description}</p></div>;
  if (/sticky|overlay|parallax|hover effects|global block|grouped sections/.test(normalized)) return <section style={{ ...style, ...(normalized.includes('parallax') ? { backgroundAttachment: 'fixed' } : {}), ...(normalized.includes('sticky') ? { position: 'sticky', top: 16, zIndex: 10 } : {}) }} className="rounded-2xl border-2 border-black bg-gradient-to-br from-white via-yellow/20 to-pink/20 p-6"><h3 className="text-2xl font-black">{editable('title', title)}</h3><p className="mt-2 max-w-2xl text-neutral-700">{editable('description', description)}</p><div className="mt-5 grid gap-3 sm:grid-cols-2">{safeItems.slice(0, 4).map((item, index) => <div key={index} className="rounded-xl border-2 border-black/15 bg-white/80 p-4"><h4 className="font-black">{String(item.title || `Layer ${index + 1}`)}</h4><p className="mt-1 text-sm text-neutral-600">{String(item.description || 'Editable content layer')}</p></div>)}</div></section>;
  if (/analytics|sandboxed html|html block|iframe|embed|calendly|typeform|payments|stripe|paypal/.test(normalized)) return <section style={style} className="rounded-2xl border-2 border-black bg-white p-5"><h3 className="font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p><label className="mt-4 block font-mono text-[10px] font-bold uppercase">Endpoint or source URL<input value={String(element.content.url || element.content.src || '')} onChange={(event) => updateContent('url', event.target.value)} className="mt-1 w-full rounded-lg border-2 border-black px-3 py-2 font-sans text-sm font-normal normal-case" placeholder="https://…" /></label>{/sandboxed html|html block/.test(normalized) && <div className="mt-4 overflow-hidden rounded-xl border border-black/20 bg-neutral-50 p-3 text-xs text-neutral-600">Sandbox preview is isolated. Add a URL or HTML payload in the inspector.</div>}{/analytics/.test(normalized) && <p className="mt-3 rounded-lg bg-emerald-100 p-3 text-sm font-bold">Analytics configuration is ready and will be applied on publish.</p>}{/payments/.test(normalized) && <button type="button" onClick={() => setSubmitted(true)} className="mt-4 rounded-lg border-2 border-black bg-yellow px-4 py-2 font-bold">Pay securely</button>}</section>;
  return <article style={style} className="overflow-hidden rounded-2xl border-2 border-black bg-white shadow-[3px_3px_0_#000]"><header className="border-b border-black/10 px-5 py-4"><p className="font-mono text-[10px] font-bold uppercase tracking-widest text-pink-600">{blockLabel}</p><h3 className="mt-1 text-xl font-black">{editable('title', title)}</h3><p className="mt-1 text-sm text-neutral-600">{editable('description', description)}</p></header><div className="grid gap-3 p-4 sm:grid-cols-2">{safeItems.slice(0, 6).map((item, index) => <article key={index} className="rounded-xl border border-black/15 bg-neutral-50 p-4"><h4 className="font-black">{String(item.title || `Item ${index + 1}`)}</h4><p className="mt-1 text-sm leading-relaxed text-neutral-600">{String(item.description || item.desc || 'Add supporting content.')}</p></article>)}</div>{actionLabel && <div className="px-5 pb-5">{button(actionLabel)}</div>}</article>;
}

function TabWidget({ items }: { items: Array<Record<string, unknown>> }) {
  const [active, setActive] = useState(0);
  return <div><div role="tablist" className="flex flex-wrap gap-2">{items.map((item, index) => <button key={index} type="button" role="tab" aria-selected={active === index} onClick={() => setActive(index)} className={`rounded-lg border border-black px-3 py-1.5 text-sm font-bold ${active === index ? 'bg-yellow' : 'bg-white'}`}>{String(item.title || `Tab ${index + 1}`)}</button>)}</div><div role="tabpanel" className="mt-3 rounded-lg bg-white/70 p-3 text-sm">{String(items[active]?.description || 'Add content for this tab.')}</div></div>;
}
